/**
 * Returns the invoice number printed on the PDF and in the accounting export,
 * e.g. `INV-2026-000123`. The sequence is zero-padded to six digits because the
 * accounting export sorts invoice numbers as text.
 */
export function formatInvoiceNumber(year, sequence) {
  if (!Number.isInteger(year) || year < 1000 || year > 9999) {
    throw new RangeError(`Invoice year must be a four-digit integer, got ${year}`);
  }
  if (!Number.isInteger(sequence) || sequence < 1 || sequence > 999999) {
    throw new RangeError(`Invoice sequence must be an integer from 1 to 999999, got ${sequence}`);
  }
  return `INV-${year}-${String(sequence).padStart(6, '0')}`;
}

